      <article><h2>{{section.title}}</h2><p class="abb-intro">{{section.intro}}</p><section v-for="item in section.items" :key="item.title" class="abb-reference-card"><h3>{{item.title}}</h3><p>{{item.text}}</p><button v-if="item.document" class="manual-open" @click="openedDocument=item.document">查看全文 →</button></section><p class="abb-source">依据：{{section.source}}</p><a :href="abbManual.library" target="_blank" rel="noopener noreferrer">ABB 官方资料库 ↗</a></article>
    </div>
    <AbbPendantControl v-else :primary-view="primaryView" :joints="joints" :joint-limits="jointLimits" :playing="motionPlaying" :program-running="programRunning" :program-status="programStatus" :program-current="programCurrent" :program-context="programContext" :program-speed="programSpeed" @program-command="$emit('program-command',$event)" @target="$emit('target',$event)" @jog="$emit('jog',$event)" @demo="$emit('demo',$event)" @home="$emit('home')" @move="$emit('move',$event)" @stop="$emit('stop')"/>
