import {ref,computed} from 'vue'
import {ElDialog} from 'element-plus'
import AbbPendantControl from './AbbPendantControl.vue'
import AbbDocumentReader from './AbbDocumentReader.vue'
import {abbManual,abbTechnicalSections,abbDocuments} from '../../utils/abb-guide.mjs'
const props=defineProps({mode:{type:String,default:'technical'},joints:{type:Array,default:()=>[0,0,0,0,90,0]},jointLimits:{type:Array,default:undefined},motionPlaying:Boolean,programRunning:Boolean,programStatus:String,programCurrent:Object,programContext:Object,programSpeed:Number})
const emit=defineEmits(['close','target','jog','demo','home','move','stop','program-command'])
function onDialogValue(value){if(!value)emit('close')}
const primaryView=ref('robot')
const sectionId=ref('spec'),openedDocument=ref('')
const section=computed(()=>abbTechnicalSections.find(s=>s.id===sectionId.value))
const currentDocument=computed(()=>props.mode==='technical'?abbDocuments[openedDocument.value]||null:null)
